function hammingDistanceBits(hexA, hexB) {
  let a = BigInt('0x' + hexA);
  let b = BigInt('0x' + hexB);
  let x = a ^ b;
  let count = 0;
  while (x > 0n) {
    count += Number(x & 1n);
    x >>= 1n;
  }
  return count;
}

